// Ctx is the whole shared state between JS and Go for one tick. JS fills In,
// Terrain, Res, RespIdx and Resp; Go fills Out, Cmd, Qry, Arena and Bytes.
type Ctx struct {
	In         [InLen]int32
	Out        [OutLen]int32
	Cmd        [CmdCap * CmdWords]int32
	Qry        [QryCap * CmdWords]int32
	Arena      [ArenaCap]int32
	Bytes      [BytesCap]byte
	Resp       [RespCap]int32
	RespIdx    [QryCap * 2]int32
	Res        [CmdCap]int32
	Terrain    [TerrainLen]byte
	StoreArena [StoreArenaCap]int32
}

// Time reads header word time.
func (c *Ctx) Time() int32 { return c.In[HdrTime] }

// CpuLimit reads header word cpuLimit.
func (c *Ctx) CpuLimit() int32 { return c.In[HdrCpuLimit] }

// CpuTickLimit reads header word cpuTickLimit.
func (c *Ctx) CpuTickLimit() int32 { return c.In[HdrCpuTickLimit] }

// CpuBucket reads header word cpuBucket.
func (c *Ctx) CpuBucket() int32 { return c.In[HdrCpuBucket] }

// CpuUnlocked reads header word cpuUnlocked.
func (c *Ctx) CpuUnlocked() int32 { return c.In[HdrCpuUnlocked] }

// CpuUnlockedTime reads header word cpuUnlockedTime.
func (c *Ctx) CpuUnlockedTime() int32 { return c.In[HdrCpuUnlockedTime] }

// CpuUsed reads header word cpuUsed.
func (c *Ctx) CpuUsed() int32 { return c.In[HdrCpuUsed] }

// GclLevel reads header word gclLevel.
func (c *Ctx) GclLevel() int32 { return c.In[HdrGclLevel] }

// GclProgress reads header word gclProgress.
func (c *Ctx) GclProgress() int32 { return c.In[HdrGclProgress] }

// GclTotal reads header word gclTotal.
