// FindByID returns the handle of the object whose packed id words match, or -1.
// Object handles change every tick; ids (idA/idB/idC) are the stable identity.
func (c *Ctx) FindByID(a, b, d int32) Handle {
	for i, n := 0, c.NCreep(); i < n; i++ {
		if c.CreepIdA(i) == a && c.CreepIdB(i) == b && c.CreepIdC(i) == d {
			return c.CreepH(i)
		}
	}
	for i, n := 0, c.NPowercreep(); i < n; i++ {
		if c.PowercreepIdA(i) == a && c.PowercreepIdB(i) == b && c.PowercreepIdC(i) == d {
			return c.PowercreepH(i)
		}
	}
	for i, n := 0, c.NStructure(); i < n; i++ {
		if c.StructureIdA(i) == a && c.StructureIdB(i) == b && c.StructureIdC(i) == d {
			return c.StructureH(i)
		}
	}
	for i, n := 0, c.NSource(); i < n; i++ {
		if c.SourceIdA(i) == a && c.SourceIdB(i) == b && c.SourceIdC(i) == d {
			return c.SourceH(i)
		}
	}
	for i, n := 0, c.NMineral(); i < n; i++ {
		if c.MineralIdA(i) == a && c.MineralIdB(i) == b && c.MineralIdC(i) == d {
			return c.MineralH(i)
		}
	}
	for i, n := 0, c.NDeposit(); i < n; i++ {
		if c.DepositIdA(i) == a && c.DepositIdB(i) == b && c.DepositIdC(i) == d {
			return c.DepositH(i)
		}
	}
	for i, n := 0, c.NSite(); i < n; i++ {
		if c.SiteIdA(i) == a && c.SiteIdB(i) == b && c.SiteIdC(i) == d {
			return c.SiteH(i)
		}
	}
	for i, n := 0, c.NResource(); i < n; i++ {
		if c.ResourceIdA(i) == a && c.ResourceIdB(i) == b && c.ResourceIdC(i) == d {
			return c.ResourceH(i)
		}
	}
	for i, n := 0, c.NTombstone(); i < n; i++ {
		if c.TombstoneIdA(i) == a && c.TombstoneIdB(i) == b && c.TombstoneIdC(i) == d {
			return c.TombstoneH(i)
		}
	}
	for i, n := 0, c.NRuin(); i < n; i++ {
		if c.RuinIdA(i) == a && c.RuinIdB(i) == b && c.RuinIdC(i) == d {
			return c.RuinH(i)
		}
	}
	for i, n := 0, c.NNuke(); i < n; i++ {
		if c.NukeIdA(i) == a && c.NukeIdB(i) == b && c.NukeIdC(i) == d {
			return c.NukeH(i)
		}
	}
	return -1
}

// CreepParts returns creep i's total and active (hits > 0) count of body part p (Part* constants).
func (c *Ctx) CreepParts(i, p int) (total, active int32) {
	b := CreepBase + i*CreepStride + 18 + 2*p
	return c.In[b], c.In[b+1]
}

// CreepAttack emits Creep.attack(h).
func (c *Ctx) CreepAttack(recv Handle, a0 Handle) {
	c.emit(OpCreepAttack, 0, int32(recv), int32(a0), 0, 0, 0, 0)
}

// CreepAttackApproach is CreepAttack, then moveTo(target, preset) if the result is ERR_NOT_IN_RANGE.
func (c *Ctx) CreepAttackApproach(recv Handle, a0 Handle, move Preset) {
	c.emit(OpCreepAttack, 0x8000|int32(move)<<16, int32(recv), int32(a0), 0, 0, 0, 0)
}

